private val copy=mapOf("teacher" to ("AI Teacher" to "Explain concepts, simplify difficult topics, check understanding, and recommend what to study next."),"quiz" to ("Practice Quiz" to "Practice by subject, topic, and difficulty, then identify weak topics."),"examiner" to ("Formal Examiner" to "Take formal assessments separately from practice, with marks, feedback, and weak areas."),"progress" to ("Progress" to "Track study time, sessions, practice, assessments, mastery, and readiness estimates."),"library" to ("Document Library" to "Keep notes, textbooks, past papers, and transcripts together."),"report" to ("Weekly Report" to "Review real study time, sessions, results, strong areas, weak areas, and recommendations."))
@Composable fun FeatureScreen(route:String,onBack:()->Unit){val item=copy[route]?: ("Study System" to "Your academic operating system.");var text by remember{mutableStateOf("")};Column(Modifier.fillMaxSize().padding(20.dp)){TextButton(onBack){Text("← Dashboard")};Text(item.first,style=MaterialTheme.typography.headlineSmall);Spacer(Modifier.height(8.dp));Text(item.second,style=MaterialTheme.typography.bodyLarge);Spacer(Modifier.height(20.dp));Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text("CONNECTED STUDY MODULE",style=MaterialTheme.typography.labelMedium);Text("Use this module with your subjects, timer sessions, documents, quizzes, and saved results.")}};if(route=="teacher"){Spacer(Modifier.height(16.dp));OutlinedTextField(text,{text=it},Modifier.fillMaxWidth(),label={Text("Ask your Teacher")});Button({text=if(text.isBlank())"Type a question first" else "Question saved: $text"},Modifier.padding(top=10.dp)){Text("Ask")}}else{Spacer(Modifier.height(20.dp));Text("Next action",style=MaterialTheme.typography.titleMedium);Text("Choose a subject and topic, complete the activity, then return to Progress to review the result.",Modifier.padding(top=8.dp))}}}
